const scene = new THREE.Scene();
scene.background = new THREE.Color(C.paper);
scene.fog = new THREE.Fog(C.paper, 100, 340);

const camera = new THREE.PerspectiveCamera(40, innerWidth/innerHeight, 0.1, 400);
camera.position.set(2, 16, 95);
camera.lookAt(0, 12, 0);

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xfff4dd, 0x33456b, 1.2));
const sun = new THREE.DirectionalLight(0xffeecb, 1.3);
sun.position.set(-10, 25, 20);
scene.add(sun);

function flatMesh(geo, color){
  return new THREE.Mesh(geo, new THREE.MeshStandardMaterial({color, flatShading:true, roughness:0.9}));
}

